import 'dart:async';

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:provider/provider.dart';

import '../config/app_theme.dart';
import '../models/job.dart';
import '../providers/job_provider.dart';

/// Asks the customer to type the completion code.
/// Returns true when the job was completed.
///
/// The code is generated by the server when "Mark Complete" is pressed and is
/// delivered to the fundi, who reads it out when the work is really done.
Future<bool> showCompletionOtpDialog(BuildContext context, Job job) async {
  final ok = await showDialog<bool>(
    context: context,
    barrierDismissible: false,
    builder: (_) => _CompletionOtpDialog(job: job),
  );
  return ok == true;
}

class _CompletionOtpDialog extends StatefulWidget {
  final Job job;
  const _CompletionOtpDialog({required this.job});

  @override
  State<_CompletionOtpDialog> createState() => _CompletionOtpDialogState();
}

class _CompletionOtpDialogState extends State<_CompletionOtpDialog> {
  final _controller = TextEditingController();
  String? _error;
  bool _submitting = false;
  int _cooldown = 60;
  Timer? _timer;

  @override
  void initState() {
    super.initState();
    _startCooldown();
  }

  @override
  void dispose() {
    _timer?.cancel();
    _controller.dispose();
    super.dispose();
  }

  void _startCooldown() {
    _timer?.cancel();
    setState(() => _cooldown = 60);
    _timer = Timer.periodic(const Duration(seconds: 1), (t) {
      if (!mounted) return t.cancel();
      if (_cooldown <= 1) {
        t.cancel();
      }
      setState(() => _cooldown = (_cooldown - 1).clamp(0, 60));
    });
  }

  Future<void> _verify() async {
    final code = _controller.text.trim();
    if (code.length != 6) {
      setState(() => _error = 'Enter the 6-digit code.');
      return;
    }

    final provider = context.read<JobProvider>();
    setState(() {
      _submitting = true;
      _error = null;
    });

    final ok = await provider.verifyCompletion(widget.job.id, code);
    if (!mounted) return;

    if (ok) {
      Navigator.of(context).pop(true);
    } else {
      setState(() {
        _submitting = false;
        _error = provider.error ?? 'Could not verify the code.';
      });
    }
  }

  Future<void> _resend() async {
    final provider = context.read<JobProvider>();
    final ok = await provider.requestCompletion(widget.job.id);
    if (!mounted) return;
    if (ok) {
      _controller.clear();
      setState(() => _error = null);
      _startCooldown();
    } else {
      setState(() => _error = provider.error ?? 'Could not send a new code.');
    }
  }

  @override
  Widget build(BuildContext context) {
    return Dialog(
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(22)),
      child: Padding(
        padding: const EdgeInsets.fromLTRB(22, 22, 22, 16),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            const Icon(Icons.verified_user_rounded,
                size: 40, color: AppTheme.primary),
            const SizedBox(height: 12),
            const Text(
              'Confirm completion',
              style: TextStyle(fontSize: 18, fontWeight: FontWeight.w800),
            ),
            const SizedBox(height: 8),
            Text(
              'Ask ${widget.job.technicianName} for the 6-digit code and enter '
              'it here to close job ${widget.job.jobNumber}.',
              textAlign: TextAlign.center,
              style: TextStyle(
                  fontSize: 13.5, height: 1.4, color: Colors.grey.shade700),
            ),
            const SizedBox(height: 18),
            TextField(
              controller: _controller,
              autofocus: true,
              enabled: !_submitting,
              keyboardType: TextInputType.number,
              textAlign: TextAlign.center,
              maxLength: 6,
              inputFormatters: [FilteringTextInputFormatter.digitsOnly],
              style: const TextStyle(
                  fontSize: 26, fontWeight: FontWeight.w800, letterSpacing: 10),
              decoration: InputDecoration(
                counterText: '',
                hintText: '••••••',
                errorText: _error,
                border: OutlineInputBorder(borderRadius: BorderRadius.circular(14)),
              ),
              onSubmitted: (_) => _verify(),
            ),
            const SizedBox(height: 6),
            TextButton(
              onPressed: (_cooldown > 0 || _submitting) ? null : _resend,
              child: Text(
                _cooldown > 0 ? 'Resend code in ${_cooldown}s' : 'Send a new code',
              ),
            ),
            const SizedBox(height: 4),
            Row(
              children: [
                Expanded(
                  child: OutlinedButton(
                    onPressed:
                        _submitting ? null : () => Navigator.of(context).pop(false),
                    style: OutlinedButton.styleFrom(
                      padding: const EdgeInsets.symmetric(vertical: 13),
                      shape: RoundedRectangleBorder(
                          borderRadius: BorderRadius.circular(12)),
                    ),
                    child: const Text('Later'),
                  ),
                ),
                const SizedBox(width: 10),
                Expanded(
                  child: ElevatedButton(
                    onPressed: _submitting ? null : _verify,
                    style: ElevatedButton.styleFrom(
                      backgroundColor: AppTheme.primary,
                      foregroundColor: Colors.white,
                      elevation: 0,
                      padding: const EdgeInsets.symmetric(vertical: 13),
                      shape: RoundedRectangleBorder(
                          borderRadius: BorderRadius.circular(12)),
                    ),
                    child: _submitting
                        ? const SizedBox(
                            width: 18,
                            height: 18,
                            child: CircularProgressIndicator(
                                strokeWidth: 2, color: Colors.white),
                          )
                        : const Text('Confirm'),
                  ),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }
}
